local UIActivityRecallDialog = Class("UIActivityRecallDialog")

function UIActivityRecallDialog:__init()
end

function UIActivityRecallDialog:__delete()
    self.controller = nil
end

function UIActivityRecallDialog:Awake()
    SetButtonAction(self.TextPlayExplain, Bind(self, self.OnClickRuleBtnHandler_))
    SetButtonAction(self.BtnCode, Bind(self, self.OnClickCopyCodeBtnHandler_))
    self:InstallShareButton_(self.FontStyleButton)
end

function UIActivityRecallDialog:OnDestroy()
    self.controller = nil --删除lua层引⽤用到的c#对象,否则不不会产⽣生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end


function UIActivityRecallDialog:Refresh(activityDojo)
    self.activityDt   = activityDojo
    self:RefreshCurrencyBarInfo()
    GameUtils.Request(Interfaces.ActivityRecall, {activityUuid = self:GetActivityId()},
            function(request, response)
                if checkNumber(response.errCode) == 0 then
                    self.recallData = response.data
                    self.recallConf = checkTable(self.recallData.recallConf)

                    self:RefreshBaseView()
                    self:RefreshAllRewards()
                    self:RefreshRed()
                    self:RefreshPlayer()
                end
            end
    )
end

function UIActivityRecallDialog:RefreshCurrencyBarInfo()
    CfUtils.SetTopCommonActive(true, false)
end

