------------------------------------------------ public

function UIActivityRecallDialog:RefreshBaseView()
    KTool.SetActive(self.TextPlayExplain, checkInt(self:GetRecallConf().ruleId) > 0)
    CfUtils.FillText(self.TxtTime, ActivityUtils.ConventActivityDurationTime(self:GetActivityDojo().startTime, self:GetActivityDojo().endTime))
    CfUtils.FillText(self.TxtContent, string.trim(self:GetActivityDojo().detail) ~= "" and self:GetActivityDojo().detail or "TO BE CONTINUE")

    local titleImgUrl = checkString(self:GetActivityDojo().titleImage)
    if string.len(titleImgUrl) > 0 then
        CfUtils.FillWebRawImage(self.ImgTitleName, titleImgUrl)
    end
    CfUtils.FillText(self.TxtCode, self:GetRecallDt().recallCode)
end

function UIActivityRecallDialog:RefreshAllRewards()
    for index = 1, self.RewardList.childCount do
        local node = self.RewardList:Find("RewardNode"..index)
        local data = self:GetRecallDt().recallRewardsConf[index]
        if not KTool.IsNull(node) then
            self:RefreshRewardCell(node, data, index)
        end
    end
end

---@param rewardDt {id : int, recallNum : int, rewards : list, status : int}
function UIActivityRecallDialog:RefreshRewardCell(node, rewardDt, index)
    local rewardNode = node:Find("RewardNode")
    local TxtNum     = rewardNode:Find("TxtNumber")
    local GoodNode   = rewardNode:Find("GoodNode")
    local btnGet     = rewardNode:Find("FontStyleButton")

    CfUtils.FillText(TxtNum, rewardDt.recallNum)
    local goodEnv = CfUtils.GetLuaScr(GoodNode, "Game.Behaviours.GoodNodeMB")
    if goodEnv then
        local reward = rewardDt.rewards[1]
        goodEnv:Reload( {
            goodsId = reward.goodsId,
            isShowNo = true, text = 'x' .. FormatCurrencyNum(reward.num)
        })
        goodEnv:SetClickButtonAction(function()
            self:OnClickDrawBtnHandler_(rewardDt, index)
        end)
    end
    self:RefreshRewardStatus(node, rewardDt.status)
    SetButtonAction(btnGet, function()
        self:OnClickDrawBtnHandler_(rewardDt, index)
    end)
end

function UIActivityRecallDialog:RefreshRewardStatus(node, status)
    local rewardNode = node:Find("RewardNode")
    local canGet     = node:Find("UIFX_DailyPanelSelected")
    local canGet1    = node:Find("UIFX_ActivityRecallPanelCompletion")
    local image1     = node:Find('ImgTransparent'):Find("Glow"):Find("Image")
    local image2     = node:Find("ImgTransparent2")
    local ImgBg      = rewardNode:Find("ImgBg1")
    local TxtTitle   = rewardNode:Find("TxtRecallTitle")
    local TxtNum     = rewardNode:Find("TxtNumber")
    local GetGroup   = rewardNode:Find('GetGroup')
    local locked     = rewardNode:Find("NotGetGroup")
    local btnGet     = rewardNode:Find("FontStyleButton")

    local isCan  = status == Constants.GetStatus.Can
    local isGot  = status == Constants.GetStatus.Has
    local isLock = status == Constants.GetStatus.Not
    KTool.SetActive(canGet, isCan)
    KTool.SetActive(canGet1, isCan)
    KTool.SetActive(GetGroup, isGot)
    KTool.SetActive(locked, isLock)
    KTool.SetActive(btnGet, isCan)

    -- 1为已达成、2为未达成、3为可领取
    CfUtils.SetUISwitchImage(image1, isCan and 3 or (isGot and 1 or 2))
    CfUtils.SetUISwitchImage(image2, isCan and 3 or (isGot and 1 or 2))

    -- 1为正常态，2为可领取
    CfUtils.SetUISwitchImage(ImgBg, isCan and 2 or 1)
    CfUtils.SetUISwitchText(TxtTitle, isCan and 2 or 1)
    CfUtils.SetColor(TxtNum,isCan and XLuaUtils.HexToColor("#ff1daa") or XLuaUtils.HexToColor("#737373"))
end

---@param playerDt {avatar : int, name : str, avatarFrame : int}
function UIActivityRecallDialog:RefreshPlayerCell(playerNode, playerDt)
    playerNode = playerNode.transform
    playerDt   = checkTable(playerDt)

    local btnEmpty = playerNode:Find("BtnEmpty")
    local roleNode = playerNode:Find("PeopleNode")
    local isHasPlayer = next(playerDt) ~= nil
    KTool.SetActive(btnEmpty, not isHasPlayer)
    KTool.SetActive(roleNode, isHasPlayer)
    if isHasPlayer then
        local txtName  = roleNode:Find("ImgTitleBg"):Find("TxtName")
        local headNode = roleNode:Find("CommonPlayerHeadNode")
        local headEnv  = CfUtils.GetLuaScr(headNode, "Game.Behaviours.CommonPlayerHeadNode")
        if headEnv then
            headEnv:FreshAvatarFrame(playerDt.avatar, playerDt.avatarFrame)
        end
        CfUtils.FillText(txtName, playerDt.name)
    end

    self:InstallShareButton_(btnEmpty)
end

function UIActivityRecallDialog:RefreshPlayer()
    local count = checkInt(self:GetRecallConf().recallLimit)
    local progress = #self:GetRecallDt().playerRecall
    self.ImgFillLine.fillAmount = progress / count
    CfUtils.FillText(self.TxtNumber, string.format("<size=56>%s</size>/%s", progress, count))
    if not self.FriendList.IsListViewInit then
        self.FriendList:InitGridView(count, function(gridView, index)
            if index < 0 then return end
            local node = gridView:NewListViewItem("RoleCell")
            if not KTool.IsNull(node) then
                self:RefreshPlayerCell(node, self:GetPlayerDt()[index + 1])
            end
            return node
        end)
    else
        GameUtils.ReloadData(self.FriendList, count)
    end
end

function UIActivityRecallDialog:RefreshRed()
    local hasRed = false
    ---@param rewardDt {id : int, recallNum : int, rewards : list, status : int}
    for _, rewardDt in ipairs(self:GetRecallDt().recallRewardsConf) do
        if rewardDt.status == Constants.GetStatus.Can then
            hasRed = true
            break
        end
    end
    ActivityUtils.UpdateActivityMainRedPointState(self:GetActivityId(), hasRed and 0 or -1)
end
------------------------------------------------- handler

function UIActivityRecallDialog:InstallShareButton_(shareButton)
    GameUtils.InstallShareButton(shareButton, Constants.ShareType.RECALL_MESSAGE, 'Prefabs/Activity/ShareActivityBackPanel.prefab', function(shareParms, previewArgs)
        local parameters = {
            code    = self:GetRecallDt().recallCode,
            sceneId = self:GetRecallConf().recallBgImages,
            desc    = self:GetRecallDt().recallShareDetail,
            title   = self:GetRecallConf().shareTitleId,
        }
        shareParms.prefabArgs      = parameters
        shareParms.isWaitCompleted = true
        previewArgs.shareMsgArgs   = {_recallCode_ = self:GetRecallDt().recallCode}
        previewArgs.bgImgPath      = ActivityUtils.GetImageFullPath(self:GetRecallConf().shareSettingId)
    end)
end

---@param rewardDt {id : int, recallNum : int, rewards : list, status : int}
function UIActivityRecallDialog:OnClickDrawBtnHandler_(rewardDt, index)
    local rewardNode = self.RewardList:Find("RewardNode"..index)
    local node       = rewardNode:Find("RewardNode"):Find("GoodNode")

    if rewardDt.status == Constants.GetStatus.Can then
        GameUtils.Request(Interfaces.ActivityRecallDraw, {activityUuid = self:GetActivityId(), rewardId = rewardDt.id},
            function(request, response)
                if checkNumber(response.errCode) == 0 then

                    -- refresh data
                    rewardDt.status = Constants.GetStatus.Has
                    self:RefreshRewardStatus(rewardNode, Constants.GetStatus.Has)

                    -- refresh reward
                    GoodsUtils.DrawRewards(response.data.rewards, true)
                    UIModule.OpenDialog(
                            {
                                id = Constants.UITypeIds.UICommonRewardPop,
                                parameters = { rewards = response.data.rewards }
                            }
                    )

                    -- refresh red
                    self:RefreshRed()
                end
            end)
    else

        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(rewardDt.rewards[1].goodsId)
        if isTable(vo) then
            GameUtils.ShowCommonTipsBoard(node.gameObject, vo.name, vo.desc, vo.quality, vo.id)
        end
    end
end

function UIActivityRecallDialog:OnClickRuleBtnHandler_()
    CfUtils.ShowModuleToast(self:GetRecallConf().ruleId)
end

function UIActivityRecallDialog:OnClickCopyCodeBtnHandler_()
    GameUtils.SecondConfirm(localize("是否确认复制【召回码】到剪切板？"), function()
        DeviceID.CopyToClipboard(self:GetRecallDt().recallCode)
        GameUtils.Toast(localize("召回码已复制"))
    end, nil, nil, 4)
end

return UIActivityRecallDialog